<script setup lang="ts">import {ref,computed} from 'vue';import type {Corpus,Document,User,Withdrawal} from '../types/domain';import {corpusApi} from '../api/corpora';import {useAsync} from '../hooks/useAsync';import PageTitle from '../components/common/PageTitle.vue';import Table from '../components/common/Table.vue';import Badge from '../components/common/Badge.vue';import Notice from '../components/common/Notice.vue';import {date} from '../utils/format';const props=defineProps<{corpora:Corpus[];documents:Document[];whitelist:string[];withdrawals:Withdrawal[];user:User;reload:()=>Promise<any>}>();const corpusId=ref(0),show=ref(false),name=ref(''),raw=ref(''),edit=ref<Document|null>(null),title=ref(''),text=ref(''),withdrawTarget=ref<Document|null>(null),reason=ref('');const active=computed(()=>corpusId.value||props.corpora[0]?.id),docs=computed(()=>props.documents.filter(d=>d.corpus_id===active.value)),withdrawnDocs=computed(()=>props.documents.filter(d=>d.corpus_id===active.value&&d.withdrawn));const {task,act}=useAsync();function choose(d:Document){if(d.withdrawn)return;edit.value=d;title.value=d.title;text.value=d.tokens_text}function askWithdraw(d:Document){withdrawTarget.value=d;reason.value=''}async function submit(){await act(async()=>{await corpusApi.create({name:name.value,filename:name.value+'.json',description:'编辑导入的已分词摘要',documents:JSON.parse(raw.value)});await props.reload();show.value=false},'分词语料已导入')}async function withdraw(){await act(async()=>{const r=await corpusApi.withdraw(withdrawTarget!.value!.id,reason.value);await props.reload();withdrawTarget.value=null;return r},'展签已撤回；受污染旧版已隔离，替代版重算后需重新审阅')}</script><template><PageTitle index="02 / TOKEN CORPUS" title="词已经分好，口径仍要核对。" description="只按空白切词，精确匹配固定50词白名单；不做中文自动分词。白名单后或min_df后空词文档单独记录，不伪造主题得分。误收录展签可整篇撤回，受影响研究隔离重算。"><button v-if="user.role!=='viewer'" @click="show=!show">导入分词语料 ↗</button></PageTitle><Notice :error="task.error" :message="task.message"/><form class="editor" v-if="show" @submit.prevent="submit"><h2>导入5–1000份JSON文档</h2><label>语料名称<input v-model="name" required maxlength="100"/></label><label>文档JSON数组<textarea rows="6" v-model="raw" required placeholder='[{"reference":"DOC-001","title":"展签摘要","tokens_text":"陶土 材料 工艺"},…]'></textarea></label><button class="primary" :disabled="task.busy">校验并导入</button></form><div class="source-selector"><label>当前语料<select v-model="corpusId"><option :value="0" v-if="corpora[0]">默认 / {{corpora[0].name}}</option><option v-for="c in corpora" :key="c.id" :value="c.id">{{c.name}} / {{c.document_count}}篇</option></select></label><p>{{corpora.find(c=>c.id===active)?.description}}<br/>{{corpora.find(c=>c.id===active)?.filename}}<br/><small>撤回修订 {{corpora.find(c=>c.id===active)?.revision??0}} · 已撤回 {{withdrawnDocs.length}} 篇</small></p></div><div class="whitelist"><small>FIXED WHITELIST / 精确匹配</small><p>{{whitelist.join(' · ')}}</p></div><form v-if="withdrawTarget" class="editor review-box danger" @submit.prevent="withdraw"><small>WITHDRAWAL / 整篇撤回</small><h2>撤回 {{withdrawTarget.reference}}</h2><p>撤回后原文与分词文本停止对外提供；引用该展签的旧版主题、词权与已确认说明导出立即停止，只保留不含原文的追溯记录。受影响研究会生成隔离的重算替代版，须重新审阅后才能下载。</p><label>撤回原因<input v-model="reason" required maxlength="500" placeholder="误收录展签，需从研究语料移除"/></label><div class="note-actions"><button type="button" class="text-button" @click="withdrawTarget=null">取消</button><button class="primary" :disabled="task.busy">确认撤回并重算 →</button></div></form><form v-if="edit" class="editor" @submit.prevent="act(async()=>{await corpusApi.edit(edit!.id,{title,tokens_text:text});await reload();edit=null},'分词文档已修订，历史运行保持原结果')"><h2>修订 {{edit.reference}}</h2><label>标题<input v-model="title" maxlength="120" required/></label><label>已分词文本<textarea rows="4" v-model="text" maxlength="10000"/></label><button class="primary" :disabled="task.busy">保存修订</button></form><div class="section-title"><h2>原始文档样本</h2><small>展示前40 / 有效{{docs.length-withdrawnDocs.length}}，计算用全部有效文档</small></div><Table :headers="['文档 / 标题','空白分词摘要','']"><tr v-for="d in docs.slice(0,40)" :key="d.id" :class="{withdrawn:d.withdrawn}"><td><small>{{d.reference}}</small><strong>{{d.title}}</strong><small v-if="d.withdrawn">已撤回 · 记录 #{{d.withdrawal_id}} · 原文停止提供</small></td><td class="token-text"><span v-if="d.withdrawn" class="redacted">原文已撤回，不再对外提供</span><span v-else>{{d.tokens_text||'（空词文档）'}}</span></td><td><template v-if="user.role!=='viewer'&&!d.withdrawn"><button class="text-button" @click="choose(d)">编辑分词 ↗</button><button class="text-button withdraw" @click="askWithdraw(d)">撤回展签</button></template><Badge v-else-if="d.withdrawn" status="invalidated"/></td></tr></Table><div class="section-title" v-if="withdrawals.length"><h2>撤回追溯 / 不含原文</h2><small>保留引用、内容摘要、影响研究与替代运行编号</small></div><Table v-if="withdrawals.length" :headers="['撤回记录','文档引用','原因','受影响旧版 / 替代版','操作者 / 时间']"><tr v-for="w in withdrawals" :key="w.id"><td class="mono">W-{{String(w.id).padStart(3,'0')}}<small>sha256 {{w.content_sha256.slice(0,16)}}… · {{w.token_count}} 词</small></td><td><strong>{{w.reference}}</strong><small>{{w.title}}</small></td><td class="detail">{{w.reason}}</td><td><small>旧版 {{w.affected_run_ids.map(id=>'#'+id).join('、')||'无'}}<br/>替代 {{w.replacement_run_ids.map(id=>'#'+id).join('、')||'无'}}</small></td><td><small>{{w.actor}}</small>{{date(w.created_at)}}</td></tr></Table></template>
